def sum_up_to(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

print(sum_up_to(10))

def multiply(a, b):
    return a * b

print(multiply(3, 4))

def square_each(nums):
    return [x * x for x in nums]

print(square_each([1, 2, 3]))

def count_words(words):
    counter = {}
    for w in words:
        counter[w] = counter.get(w, 0) + 1
    return counter

print(count_words(["a", "b", "a"]))

def read_file(path):
    with open(path, "r", encoding="utf-8") as f:
        return f.read()

print(read_file("hello.txt"))

